schuldrecht_aufwendungssumme <- function(regelfall=NULL, aufwendungspositionen=NULL, einordnungsnachweis=NULL) {
 faelle <- list(grundstueck_erschliessungsbeitraege_verkaeufer="\u00a7436I: vom Verk\u00e4ufer zu tragende Erschlie\u00dfungs- und sonstige Anliegerbeitr\u00e4ge f\u00fcr Ma\u00dfnahmen, die bis einschlie\u00dflich des Vertragsschlusstages bautechnisch begonnen sind. Beginn und Zuordnung jeder Ma\u00dfnahme vorqualifiziert; Entstehungsdatum der Beitragsschuld ist hierf\u00fcr nicht ma\u00dfgeblich. Keine abweichende Vereinbarung; sonstige \u00f6ffentliche Lasten436II nicht pauschal einbeziehen.",
kauf_uebergabekosten_verkaeufer="\u00a7448I: rechtlich zugeordnete Kosten der \u00dcbergabe der Sache zulasten des Verk\u00e4ufers. Kosten der Abnahme oder Versendung an einen anderen Ort als den Erf\u00fcllungsort geh\u00f6ren nicht hierher. Abweichende Kostenvereinbarungen und Sonderregeln vorqualifizieren.",
kauf_abnahme_versand_grundbuchkosten_kaeufer="\u00a7448I/II: rechtlich zugeordnete K\u00e4uferkosten der Abnahme und Versendung an einen anderen Ort als den Erf\u00fcllungsort sowie bei Grundst\u00fcckskauf Beurkundung des Kaufvertrags und der Auflassung, Grundbucheintragung und erforderliche Erkl\u00e4rungen. Nur tats\u00e4chlich einschl\u00e4gige Kostenkategorien einbeziehen; keine Berechnung von Geb\u00fchrens\u00e4tzen. Abweichende Vereinbarungen und Sonderregeln vorqualifizieren.",
zahlung_fehlerentgelte_zinsen="\u00a7675yVI: in Zusammenhang mit nicht erfolgter oder fehlerhafter Ausf\u00fchrung in Rechnung gestellte oder belastete Entgelte und Zinsen; nur rechtlich erstattungsf\u00e4hige Positionen. Zahlungsbetrag und dessen Kontokorrektur sowie sonstiger Schaden675z getrennt halten. Jede Geb\u00fchr/Zinsposition nur einmal, bereits erstattete Betr\u00e4ge separat anrechnen.",
landpacht_notwendige_verwendungen="\u00a7590b: notwendige Verwendungen auf die Pachtsache; rechtliche Erforderlichkeit und Pflichtenzuordnung vorqualifiziert. Andere als notwendige Verwendungen591 und Wegnahmerechte591a gesondert. Vorsch\u00fcsse oder geleisteter Ersatz sind keine zus\u00e4tzlichen Verwendungen.",
vergebliche_vertrauensaufwendungen="\u00a7284: nur billigerweise im Vertrauen auf Leistung get\u00e4tigte, ersatzf\u00e4hige vergebliche Aufwendungen. Alternative zum Schadensersatz statt der Leistung; kein zus\u00e4tzlicher Ersatz beider Positionen. Zweckverfehlung auch ohne Pflichtverletzung, Zurechnung und weitere Anspruchsgrenzen vorqualifizieren.",
mietmangel_selbstbeseitigung="\u00a7536aII: erforderliche Selbstbeseitigungsaufwendungen bei vorqualifiziertem Vermieterverzug oder notwendiger umgehender Bestandserhaltung/-wiederherstellung. Schadensersatz536aI separat;536b/c/d, Kenntnis, Anzeige und wirksame Vertragsregelungen vorqualifizieren.",
miete_erhaltung_modernisierung="\u00a7555aIII und555dVI: infolge Erhaltungs-/Modernisierungsma\u00dfnahme notwendige, im angemessenen Umfang ersatzf\u00e4hige Mieteraufwendungen. Keine Modernisierungsumlage559; Vorsch\u00fcsse und bereits geleisteter Ersatz separat anrechnen, nicht nochmals als Aufwand z\u00e4hlen.",
auftrag_aufwendungen="\u00a7670: zum Zwecke der Auftragsausf\u00fchrung gemachte Aufwendungen, die den Umst\u00e4nden nach f\u00fcr erforderlich gehalten werden durften. Keine automatische Verg\u00fctung eigener T\u00e4tigkeit; Vorschuss669 und Herausgabe667 getrennt abrechnen.",
kauf_nacherfuellung="\u00a7439II/III/VI2: erforderliche Nacherf\u00fcllungsaufwendungen einschlie\u00dflich qualifizierter Transport-, Wege-, Arbeits-, Material-, Ausbau-/Einbau- und R\u00fccknahmekosten. Anspruchsvoraussetzungen, Verweigerungsrechte und konkrete Zuordnung vorqualifizieren; keine Doppelz\u00e4hlung von Material in Gesamtwerkrechnung.",
lieferantenregress="\u00a7445aI/III: im konkreten Lieferverh\u00e4ltnis regressf\u00e4hige Aufwendungen aus439II/III/VI2 und475V. Neu hergestellte Sache, ma\u00dfgeblicher Mangel/Aktualisierungspflicht und gegebenenfalls Unternehmereigenschaft der Lieferkette vorqualifiziert. Nicht s\u00e4mtliche eigenen Betriebskosten; weitere Rechte und377HGB gesondert.",
teilzeitwohnrecht_widerrufskosten="\u00a7357cI: dem Verbraucher zu erstattende Vertrags-, Durchf\u00fchrungs- und R\u00fcckabwicklungskosten nach qualifiziertem Widerruf. Keine Verg\u00fctung von Diensten/Nutzungs\u00fcberlassung zugunsten des Unternehmers einrechnen; etwaiger Wertersatz357cII separat, nicht automatisch aufrechnen.")
 faelle[["teilzahlung_ruecktritt_508"]] <- "\u00a7508Satz3/6: infolge des Vertrags gemachte, rechtlich ersatzfaehige Unternehmeraufwendungen im qualifizierten Ruecktrittsverhaeltnis. Positionen ohne Doppelzaehlung summieren. Nutzungsverguetung nachSatz4 unter Ruecksicht auf eingetretene Wertminderung gesondert bewerten; keine pauschale Gleichsetzung mit Wertverlust und kein automatischer doppelter Abzug. Gewoehnlicher Verkaufswert bei Vereinbarung nachSatz5 ist externe Bewertung zum Wegnahmezeitpunkt, keine gesetzliche Prozentformel; dieser alternative Weg nicht mit automatischem Ruecktritt vermischen."
 .auswahl(regelfall,"regelfall",names(faelle))
 summe <- .rechnungssumme(aufwendungspositionen,"aufwendungspositionen")
 .text(einordnungsnachweis,"einordnungsnachweis")
 eingaben <- list(regelfall=regelfall, aufwendungspositionen=aufwendungspositionen, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .geld_ergebnis(summe,"BGB_SCHULDRECHT_AUFWENDUNGSSUMME",eingaben,list(list(operation="Nichtnegative, ohne \u00dcberschneidung rechtlich zugeordnete Aufwendungspositionen exakt summieren.")))
 ergebnis$hinweise <- c(ergebnis$hinweise,list("Nur numerischer Summenbaustein; Anspruchsvoraussetzungen, Erforderlichkeit/Angemessenheit und rechtliche Einwendungen vorab bestimmen. Positionsbelege bleiben notwendig. Vorsch\u00fcsse, Erstattungen und Zahlungen separat zuordnen; Summe ist kein ungepr\u00fcfter offener Zahlungsanspruch.",faelle[[regelfall]]))
 ergebnis
}
